using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace AdaptiveCards
{
    /// <summary>
    /// Helper class used to convert the backgroundImage property to/from JSON.
    /// Handles both string URLs and full BackgroundImage objects.
    /// </summary>
    public class AdaptiveBackgroundImageConverter : JsonConverter<AdaptiveBackgroundImage>, ILogWarnings
    {
        /// <summary>
        /// A list of warnings generated by the converter.
        /// </summary>
        public List<AdaptiveWarning> Warnings { get; set; } = new List<AdaptiveWarning>();

        /// <summary>
        /// Initializes a new instance with an empty warnings list.
        /// </summary>
        public AdaptiveBackgroundImageConverter() { }

        /// <summary>
        /// Initializes a new instance with a shared warnings list.
        /// </summary>
        public AdaptiveBackgroundImageConverter(List<AdaptiveWarning> warnings)
        {
            Warnings = warnings ?? new List<AdaptiveWarning>();
        }

        /// <inheritdoc />
        public override void Write(Utf8JsonWriter writer, AdaptiveBackgroundImage value, JsonSerializerOptions options)
        {
            if (!string.IsNullOrEmpty(value.UrlString))
            {
                if (value.HasDefaultValues())
                {
                    writer.WriteStringValue(value.UrlString);
                }
                else
                {
                    // Serialize as a full object - need to avoid recursion
                    writer.WriteStartObject();
                    writer.WriteString("url", value.UrlString);

                    if (value.FillMode != default)
                    {
                        var name = value.FillMode.ToString();
                        writer.WriteString("fillMode", char.ToLowerInvariant(name[0]) + name.Substring(1));
                    }
                    if (value.HorizontalAlignment != default)
                    {
                        var name = value.HorizontalAlignment.ToString();
                        writer.WriteString("horizontalAlignment", char.ToLowerInvariant(name[0]) + name.Substring(1));
                    }
                    if (value.VerticalAlignment != default)
                    {
                        var name = value.VerticalAlignment.ToString();
                        writer.WriteString("verticalAlignment", char.ToLowerInvariant(name[0]) + name.Substring(1));
                    }

                    writer.WriteEndObject();
                }
            }
        }

        /// <inheritdoc />
        public override AdaptiveBackgroundImage Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
            {
                return new AdaptiveBackgroundImage(reader.GetString());
            }
            else if (reader.TokenType == JsonTokenType.StartObject)
            {
                // Deserialize as a full object — use a temporary options without this converter to avoid recursion
                var node = System.Text.Json.Nodes.JsonNode.Parse(ref reader);
                var tempOptions = new JsonSerializerOptions(options);
                // Remove this converter from temp options
                tempOptions.Converters.Clear();
                foreach (var c in options.Converters)
                {
                    if (!(c is AdaptiveBackgroundImageConverter))
                    {
                        tempOptions.Converters.Add(c);
                    }
                }
                return node.Deserialize<AdaptiveBackgroundImage>(tempOptions);
            }
            else
            {
                reader.Skip();
                return null;
            }
        }
    }
}
